pragma solidity 0.8.36;
library L { function cd(bytes calldata self) internal pure returns (uint) { return self.length; } }
contract C {
    using L for bytes;
    function memoryReceiver(bytes memory input) public pure returns (uint) { return input.cd(); }
}
